package com.franco.desco.adapter.in.web.access;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver; import com.franco.desco.adapter.in.web.common.*; import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation; import com.franco.desco.adapter.in.web.common.pagination.PageResponse; import com.franco.desco.adapter.in.web.openapi.OpenApiConstants; import com.franco.desco.application.access.RoleCommands.GetRole; import com.franco.desco.application.access.port.in.RoleUseCase; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/roles") @Tag(name="Roles y permisos",description="Administración de roles y permisos modulares.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated
public class RoleController{private final RoleUseCase u;private final RoleWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public RoleController(RoleUseCase u,RoleWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_LISTAR')") @Operation(operationId="rolesListar",summary="Listar roles") public ResponseEntity<ApiResponse<PageResponse<RoleResponses.Summary>>> list(@RequestParam(defaultValue="1") @Min(1) int pagina,@RequestParam(defaultValue="20") @Min(1) @Max(100) int tamano,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}") @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_VER')") @Operation(operationId="rolesVer",summary="Ver rol, permisos y usuarios") public ResponseEntity<ApiResponse<RoleResponses.Detail>> get(@PathVariable Long id,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.get(new GetRole(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_CREAR')") @Operation(operationId="rolesCrear",summary="Crear rol") public ResponseEntity<ApiResponse<RoleResponses.Created>> create(@Valid @RequestBody RoleRequests.Create q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.create(map.command(q),ids.resolve(a),meta.resolve(r)),r,RoleResponses.Created::new);}
 @PutMapping("/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_EDITAR')") @Operation(operationId="rolesEditar",summary="Editar rol") public ResponseEntity<ApiResponse<Void>> update(@PathVariable Long id,@Valid @RequestBody RoleRequests.Update q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/deshabilitar") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_RETIRAR')") @Operation(operationId="rolesDeshabilitar",summary="Deshabilitar rol") public ResponseEntity<ApiResponse<Void>> disable(@PathVariable Long id,@Valid @RequestBody RoleRequests.Disable q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.disable(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PutMapping("/{id}/permisos") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'ROLESPERMISOS_CREAR')") @Operation(operationId="rolesActualizarPermisos",summary="Reemplazar permisos del rol",description="Solo permite asignar permisos que el usuario actor posee.") public ResponseEntity<ApiResponse<Void>> permissions(@PathVariable Long id,@Valid @RequestBody RoleRequests.Permissions q,@Parameter(hidden=true) JwtAuthenticationToken a,@Parameter(hidden=true) HttpServletRequest r){return res.from(u.updatePermissions(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
}
